CREATE TABLE prestaciones(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE,descripcion VARCHAR(255),activo BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE sede_prestacion(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_sede BIGINT NOT NULL REFERENCES sedes(id),id_prestacion BIGINT NOT NULL REFERENCES prestaciones(id),precio NUMERIC(10,2) NOT NULL CHECK(precio>=0),duracion_minutos INTEGER NOT NULL CHECK(duracion_minutos BETWEEN 30 AND 240 AND duracion_minutos % 30=0),activo BOOLEAN NOT NULL,UNIQUE(id_sede,id_prestacion));
